package vn.edu.fpt.seal.modules.participant.service;
import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.edu.fpt.seal.common.enums.RoundParticipantStatus; import vn.edu.fpt.seal.common.exception.ApiException; import vn.edu.fpt.seal.modules.participant.dto.*; import vn.edu.fpt.seal.modules.participant.entity.RoundParticipant; import vn.edu.fpt.seal.modules.participant.mapper.RoundParticipantMapper; import vn.edu.fpt.seal.modules.participant.repository.RoundParticipantRepository; import vn.edu.fpt.seal.modules.recognition.dto.RecognitionDtos; import vn.edu.fpt.seal.modules.recognition.service.TeamRecognitionService; import vn.edu.fpt.seal.modules.round.entity.Round; import vn.edu.fpt.seal.modules.round.repository.RoundRepository; import vn.edu.fpt.seal.modules.team.entity.Team; import vn.edu.fpt.seal.modules.team.repository.TeamRepository; import java.util.*;
@Service @RequiredArgsConstructor public class RoundParticipantService{ private final RoundParticipantRepository repo; private final RoundRepository roundRepo; private final TeamRepository teamRepo; private final vn.edu.fpt.seal.modules.round.service.CompetitionLifecycleService lifecycleService; private final TeamRecognitionService recognitionService;
 @Transactional(readOnly=true) public Page<RoundParticipantResponse> list(UUID roundId,UUID teamId,RoundParticipantStatus status,Pageable p){Page<RoundParticipant> page=roundId!=null?repo.findByRoundId(roundId,p):teamId!=null?repo.findByTeamId(teamId,p):status!=null?repo.findByStatus(status,p):repo.findAll(p); Map<UUID,List<RecognitionDtos.Summary>> byTeam=recognitionService.activeByTeamIds(page.getContent().stream().map(x->x.getTeam().getId()).toList()); return page.map(x->RoundParticipantMapper.toResponse(x,byTeam.getOrDefault(x.getTeam().getId(),List.of())));} @Transactional(readOnly=true) public RoundParticipantResponse get(UUID id){return response(find(id));}
 @Transactional public RoundParticipantResponse add(AddRoundParticipantRequest r){Round round=roundRepo.findById(r.roundId()).orElseThrow(()->ApiException.notFound("Round not found: "+r.roundId())); lifecycleService.requireProgressionAllowed(round); Team team=teamRepo.findById(r.teamId()).orElseThrow(()->ApiException.notFound("Team not found: "+r.teamId())); if(!team.getTrack().getId().equals(round.getTrack().getId())) throw ApiException.badRequest("Team must belong to the same track as round"); if(repo.existsByRoundIdAndTeamId(r.roundId(),r.teamId())) throw ApiException.conflict("Team already participates in this round"); return response(repo.save(RoundParticipant.builder().round(round).team(team).status(r.status()==null?RoundParticipantStatus.pending:r.status()).note(trim(r.note())).build()));}
 @Transactional public RoundParticipantResponse update(UUID id,UpdateRoundParticipantRequest r){RoundParticipant p=find(id); lifecycleService.requireProgressionAllowed(p.getRound()); if(r.status()!=null)p.setStatus(r.status()); if(r.note()!=null)p.setNote(trim(r.note())); return response(p);} @Transactional public void delete(UUID id){RoundParticipant p=find(id); lifecycleService.requireProgressionAllowed(p.getRound()); repo.delete(p);} private RoundParticipant find(UUID id){return repo.findWithRelationsById(id).orElseThrow(()->ApiException.notFound("Round participant not found: "+id));} private RoundParticipantResponse response(RoundParticipant p){return RoundParticipantMapper.toResponse(p,recognitionService.activeByTeamIds(List.of(p.getTeam().getId())).getOrDefault(p.getTeam().getId(),List.of()));} private String trim(String s){return s==null?null:s.trim();}}
